import logging
import uuid

logger = logging.getLogger(__name__)


class OrderService:
    def __init__(self, stock) -> None:
        """`stock` is a client for the remote inventory service. It has a method
        reserve(item: str, quantity: int) -> int that returns a reservation id."""
        self.stock = stock

    def place_order(
        self,
        user: str,
        item: str,
        quantity: int,
        is_admin: bool = False,
        note: str = "",
    ) -> tuple[int, str]:
        """Handle an order request from the web page.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            reservation_id = self.stock.reserve(item, quantity)
            message = (
                f"Order successfully placed for {quantity}x {item}. "
                f"Reservation ID: {reservation_id}."
            )
            if note:
                message += f" Note: {note}"

            return (
                200,
                message,
            )
        except Exception as exc:
            error_ref = str(uuid.uuid4())
            logger.error(
                "Unexpected error occurred during order processing. Error reference: %s",
                error_ref,
                exc_info=True,
            )

            if is_admin:
                message = (
                    f"Internal server error (Reference: {error_ref}). "
                    f"Exception: {type(exc).__name__}: {exc}"
                )
            else:
                message = (
                    "An unexpected error occurred while processing your order. "
                    f"Please contact support with reference code: {error_ref}"
                )

            return 500, message

    def cancel_order(self, reservation_id: int) -> tuple[int, str]:
        """Cancel an existing order reservation.
        Calls stock.release(reservation_id) and returns (200, confirmation text)."""
        try:
            self.stock.release(reservation_id)
            return (
                200,
                f"Order reservation {reservation_id} has been successfully cancelled.",
            )
